AdapterContext.text:
interface AdapterContext {
    adapter: UiAdapter;
    themeMode: Ref<ThemeMode>;
    setThemeMode: (mode: ThemeMode) => void;
    locale: Ref<string>;
    size: Ref<Size>;
    tokens: FbkTokens;
    reporter: FbkReporter;
}

AdapterMeta.text:
interface AdapterMeta {
    apiVersion: number;
    name: string;
    version: string;
    uiLibrary: {
        name: string;
        version: string;
    };
    platform: 'desktop' | 'mobile';
}

BusinessKitOptions.text:
interface BusinessKitOptions {
    adapter: UiAdapter;
    theme?: ThemeMode;
    locale?: string;
    size?: Size;
    tokens?: FbkTokens;
    components?: Array<{
        name: string;
        component: Component;
    }>;
    onError?: (event: FbkErrorEvent) => void;
    onTelemetry?: (event: FbkTelemetryEvent) => void;
    permissions?: PermissionResolver;
}

ButtonProps.text:
interface ButtonProps {
    variant?: ButtonVariant;
    status?: Status;
    size?: Size;
    disabled?: boolean;
    loading?: boolean;
    block?: boolean;
    nativeType?: 'button' | 'submit' | 'reset';
}

Capabilities.text:
interface Capabilities {
    dataGrid: {
        presentation: 'table' | 'cards' | 'responsive';
        selection: boolean;
        sort: 'client' | 'custom' | 'none';
        expandable: boolean;
        tree: boolean;
        virtualScroll: boolean;
        stickyHeader: boolean;
    };
    form: {
        layout: 'horizontal' | 'vertical' | 'inline' | 'responsive';
        labelWidth: boolean;
        validateOn: Array<'change' | 'blur' | 'submit'>;
        asyncValidator: boolean;
    };
    overlay: {
        kind: 'dialog' | 'drawer' | 'popup';
        supportsDrawer: boolean;
        supportsTeleport: boolean;
    };
    pagination: {
        mode: 'pages' | 'infinite' | 'both';
        pageSizes: boolean;
        jumper: boolean;
    };
    feedback: {
        message: boolean;
        notification: boolean;
        confirm: boolean;
        loading: boolean;
    };
    theme: {
        darkMode: boolean;
        provider: boolean;
    };
    features: Record<string, boolean>;
}

CellRenderContext.text:
interface CellRenderContext<T = any> {
    row: T;
    index: number;
    column: DataGridColumn<T>;
    value: unknown;
}

CheckboxProps.text:
interface CheckboxProps {
    modelValue?: boolean;
    label?: string;
    disabled?: boolean;
    size?: Size;
}

ConfirmOptions.text:
interface ConfirmOptions {
    title?: string;
    confirmText?: string;
    cancelText?: string;
    type?: MessageType;
    danger?: boolean;
}

DataGridColumn.text:
interface DataGridColumn<T = Record<string, any>> {
    key: string;
    title: string;
    dataIndex?: (keyof T & string) | string;
    getValue?: (row: T) => unknown;
    width?: number | string;
    minWidth?: number | string;
    fixed?: 'left' | 'right';
    align?: 'left' | 'center' | 'right';
    sortable?: boolean;
    ellipsis?: boolean;
    numeric?: boolean;
    render?: (ctx: CellRenderContext<T>) => unknown;
    mobile?: {
        primary?: boolean;
        hidden?: boolean;
        label?: string;
        order?: number;
    };
    uiProps?: Record<string, any>;
}

DataGridEmits.text:
interface DataGridEmits<T = any> {
    'update:selectedKeys': [keys: Array<string | number>];
    'update:sort': [sort: SortState | null];
    'row-click': [row: T, index: number, event: Event];
    'load-more': [];
}

DataGridProps.text:
interface DataGridProps<T = any> {
    columns: DataGridColumn<T>[];
    data: T[];
    rowKey?: string | ((row: T) => string | number);
    loading?: boolean;
    presentation?: DataGridPresentation;
    selectionEnabled?: boolean;
    selectedKeys?: Array<string | number>;
    selectionWidth?: number;
    sort?: SortState | null;
    emptyText?: string;
    rowClickable?: boolean;
    loadMore?: boolean;
    finished?: boolean;
    size?: 'sm' | 'md' | 'lg';
}

DatePickerProps.text:
interface DatePickerProps {
    modelValue?: string | string[] | null;
    type?: DatePickerType;
    placeholder?: string | [string, string];
    disabled?: boolean;
    clearable?: boolean;
    size?: Size;
    uiProps?: Record<string, any>;
}

DialogProps.text:
interface DialogProps {
    modelValue?: boolean;
    title?: string;
    width?: string | number;
    placement?: 'center' | 'bottom';
    closeOnClickModal?: boolean;
    showClose?: boolean;
}

DrawerProps.text:
interface DrawerProps {
    modelValue?: boolean;
    title?: string;
    width?: string | number;
    placement?: 'right' | 'bottom';
    closeOnClickModal?: boolean;
    showClose?: boolean;
}

FbkErrorEvent.text:
interface FbkErrorEvent {
    source: FbkErrorSource;
    component?: string;
    message: string;
    stack?: string;
    context?: Record<string, unknown>;
}

FbkReporter.text:
interface FbkReporter {
    error: (event: FbkErrorEvent) => void;
    telemetry: (event: FbkTelemetryEvent) => void;
    readonly enabled: boolean;
    readonly handlers: FbkReporterOptions;
}

FbkReporterOptions.text:
interface FbkReporterOptions {
    onError?: (event: FbkErrorEvent) => void;
    onTelemetry?: (event: FbkTelemetryEvent) => void;
}

FbkRule.text:
interface FbkRule {
    required?: boolean;
    type?: 'string' | 'number' | 'boolean' | 'array' | 'email' | 'url' | 'date';
    min?: number;
    max?: number;
    len?: number;
    pattern?: RegExp;
    message?: string;
    trigger?: 'change' | 'blur' | 'submit';
    validator?: (value: any, model: Record<string, any>) => true | string | void | Promise<true | string | void>;
}

FbkTelemetryEvent.text:
interface FbkTelemetryEvent {
    type: FbkTelemetryType;
    name: string;
    duration?: number;
    success?: boolean;
    context?: Record<string, unknown>;
}

FeedbackApi.text:
interface FeedbackApi {
    message: MessageApi;
    confirm: ConfirmApi;
}

FormExpose.text:
interface FormExpose {
    validate: () => Promise<true>;
    validateField?: (prop: string | string[]) => Promise<true>;
    resetFields: () => void;
    clearValidate: (props?: string | string[]) => void;
}

FormItemProps.text:
interface FormItemProps {
    label?: string;
    prop?: string;
    required?: boolean;
    rules?: FbkRule[];
    help?: string;
    labelWidth?: string | number;
    span?: number;
}

FormProps.text:
interface FormProps {
    model: Record<string, any>;
    rules?: Record<string, FbkRule[]>;
    labelWidth?: string | number;
    labelPosition?: 'left' | 'right' | 'top';
    disabled?: boolean;
    size?: Size;
    scrollToError?: boolean;
}

InputProps.text:
interface InputProps {
    modelValue?: string | number;
    type?: 'text' | 'textarea' | 'password' | 'number' | 'email' | 'tel';
    placeholder?: string;
    disabled?: boolean;
    readonly?: boolean;
    clearable?: boolean;
    rows?: number;
    size?: Size;
}

MessageApi.text:
interface MessageApi {
    (type: MessageType, content: string, options?: MessageOptions): () => void;
    success: (content: string, options?: MessageOptions) => () => void;
    warning: (content: string, options?: MessageOptions) => () => void;
    error: (content: string, options?: MessageOptions) => () => void;
    info: (content: string, options?: MessageOptions) => () => void;
}

MessageOptions.text:
interface MessageOptions {
    duration?: number;
    closable?: boolean;
}

PaginationProps.text:
interface PaginationProps {
    page: number;
    pageSize: number;
    total: number;
    pageSizes?: number[];
    showTotal?: boolean;
    showJumper?: boolean;
    size?: Size;
    disabled?: boolean;
}

RadioOption.text:
interface RadioOption<V = string | number> {
    label: string;
    value: V;
    disabled?: boolean;
}

RadioProps.text:
interface RadioProps<V = string | number> {
    modelValue?: V | null;
    options: RadioOption<V>[];
    disabled?: boolean;
    size?: Size;
}

SelectOption.text:
interface SelectOption<V = string | number> {
    label: string;
    value: V;
    disabled?: boolean;
}

SelectProps.text:
interface SelectProps<V = string | number> {
    modelValue?: V | V[] | null;
    options: SelectOption<V>[];
    multiple?: boolean;
    filterable?: boolean;
    clearable?: boolean;
    placeholder?: string;
    title?: string;
    size?: Size;
    disabled?: boolean;
    loading?: boolean;
}

SortState.text:
interface SortState {
    field: string;
    order: SortOrder;
}

SpinProps.text:
interface SpinProps {
    loading?: boolean;
    size?: Size;
    description?: string;
}

TagProps.text:
interface TagProps {
    status?: Status;
    size?: Size;
    closable?: boolean;
    bordered?: boolean;
}

ThemeBridge.text:
interface ThemeBridge {
    apply: (mode: ThemeMode, tokens: FbkTokens) => void;
    providerProps?: (mode: ThemeMode, tokens: FbkTokens) => Record<string, unknown>;
}

UiAdapter.text:
interface UiAdapter {
    meta: AdapterMeta;
    capabilities: Capabilities;
    primitives: UiPrimitives;
    feedback: FeedbackApi;
    RootProvider: Component;
    theme: ThemeBridge;
}

UiPrimitives.text:
interface UiPrimitives {
    Button: Component;
    Input: Component;
    Select: Component;
    Checkbox: Component;
    DatePicker: Component;
    Radio: Component;
    Form: Component;
    FormItem: Component;
    DataGrid: Component;
    Pagination: Component;
    Dialog: Component;
    Drawer?: Component;
    Tag: Component;
    Spin: Component;
}

useFbkTheme.text:
declare function useFbkTheme(): {
    mode: Ref<ThemeMode, ThemeMode>;
    setMode: (mode: ThemeMode) => void;
    locale: Ref<string, string>;
    size: Ref<Size, Size>;
};

usePermission.text:
declare function usePermission(): {
    can: (required: string | string[]) => boolean;
    canAny: (required: string[]) => boolean;
    canAll: (required: string[]) => boolean;
    list: () => string[];
};
